/* Module 1 reference, parameter, feature, and baseline profile seed v0.2. All values are synthetic. */
BEGIN;
DO $$ DECLARE v_ps bigint;v_prod bigint;v_op bigint;v_pol bigint;v_set bigint;BEGIN
IF v_prod IS NULL THEN SELECT product_structure_profile_id INTO v_prod FROM msbf_ctl.product_legal_structure_profile WHERE profile_code='PDR_001' AND profile_version=1;END IF;
IF v_op IS NULL THEN SELECT operating_model_profile_id INTO v_op FROM msbf_ctl.operating_model_profile WHERE profile_code='DEMO_PROCESSOR_LINKED' AND profile_version=1;END IF;
IF v_ps IS NULL THEN SELECT parameter_set_id INTO v_ps FROM msbf_ctl.parameter_set WHERE parameter_set_code='M1_BASELINE_DEMO' AND parameter_set_version=1;END IF;
IF v_set IS NULL THEN SELECT scenario_set_id INTO v_set FROM msbf_ctl.scenario_set WHERE scenario_set_code='M1_BASELINE_STRESS' AND scenario_set_version=1;END IF;
END $$;
COMMIT;
